return ['domain'=>'press-permit-core% 10 == 0) ? 2 : 3)));% 10 == 0) ? 2: 3)));','plural-forms'=>'nplurals=4; plural=(n == 1 ? 0 : (n == 2 ? 1 : ((n > 10 && n % 10 == 0) ? 2 : 3)));','language'=>'he_IL10 == 0) ? 2: 3)));','project-id-version'=>'PublishPress Permissions Free 4.8.2','pot-creation-date'=>'2026-04-22T11:57:22+00:00','po-revision-date'=>'2026-05-26 19:59+0000','x-generator'=>'WP-CLI 2.12.0','messages'=>['PublishPress Permissions Free'=>'PublishPress Permissions Free','https://publishpress.com/presspermit'=>'https://publishpress.com/presspermit','PublishPress Permissions allows you to enable or deny access to posts, pages, categories, tags and more.'=>'PublishPress Permissions מאפשר לך לאפשר או למנוע גישה לפוסטים, דפים, קטגוריות, תגיות ועוד.','PublishPress'=>'PublishPress','https://publishpress.com/'=>'https://publishpress.com/','Edit Tag for All Post Types'=>'ערוך תווית לכל סוגי הפוסטים','Edit Tag for Posts'=>'ערוך תווית לפוסטים','Advanced Custom Fields'=>'שדות מותאמים מתקדמים','Control front-end access to Field Groups with advanced permission management.'=>'נהל גישה לחזית למערכות שדה עם ניהול הרשאות מתקדם.','Control access to Field Groups'=>'שלוט בגישה לקבוצות שדות','Front-end visibility restrictions'=>'מגבלות נראות בחזית','Integration with permission groups'=>'אינטגרציה עם קבוצות הרשאות','Beaver Builder'=>'בייבר בילדר','Compatibility with Edit Permissions in Beaver Builder.'=>'התאמה עם עריכת הרשאות בבייבר בילדר.','Beaver editor integration'=>'אינטגרציה עם עורך בייבר','Widget-level permission controls'=>'בקרות הרשאות ברמת ווידג\'ט','Template access restrictions'=>'מגבלות גישה לתבניות','bbPress Forums'=>'פורומים bbPress','Forum-specific permissions for bbPress with detailed control over forum access and participation.'=>'הרשאות ספציפיות לפורומים עבור bbPress עם שליטה מפורטת על גישה לפורום והשתתפות.','Forum-specific permissions'=>'הרשאות ספציפיות לפורום','Topic creation restrictions'=>'מגבלות יצירת נושא','Forum access controls'=>'בקרות גישה לפורום','BuddyPress'=>'באדי פרס','Assign post and term permissions to BuddyPress groups for enhanced content control.'=>'קבע הרשאות לפוסטים ולמונחים לקבוצות BuddyPress לשליטה משופרת על התוכן.','Assign post permissions to BuddyPress groups'=>'הקצה הרשאות פוסט לקבוצות באדי פרס','Assign term permissions to BuddyPress groups'=>'הקצה הרשאות מונח לקבוצות באדי פרס','Group-based content permissions'=>'הרשאות תוכן מבוססות קבוצות','CMS Tree View'=>'תצוגת עץ CMS','Compatibility with Edit Permissions in CMS Tree View.'=>'תאימות עם עריכת הרשאות בתצוגת עץ CMS.','Permission-aware tree view'=>'תצוגת עץ עם מודעות להרשאות','Hierarchical content controls'=>'בקרות תוכן היררכיות','Elementor'=>'אלמנטור','Compatibility with Edit Permissions in Elementor.'=>'תאימות עם עריכת הרשאות באלמנטור.','Elementor editor integration'=>'אינטגרציית עורך אלמנטור','The Events Calendar'=>'לוח השנה לאירועים','Apply permission controls to events and event-related content.'=>'החל בקרות הרשאות לאירועים ולתוכן הקשור לאירועים.','Event post permissions'=>'הרשאות פוסט לאירועים','Event taxonomy controls'=>'בקרות מיסוי לאירועים','Nested Pages'=>'דפים מקוננים','Compatibility with Edit Permissions in Nested Pages.'=>'תאימות עם עריכת הרשאות בדפים מקוננים.','Permission-aware nested view'=>'תצוגה מקננת מודעת הרשאות','Quick edit integration'=>'שילוב עריכה מהירה','PublishPress Statuses'=>'סטטוסים של PublishPress','Compatibility with PublishPress Statuses plugin.'=>'תאימות עם תוסף הסטטוסים של PublishPress.','Custom status permissions'=>'הרשאות סטטוס מותאמות אישית','Workflow-specific access controls'=>'בקרות גישה ספציפיות לזרימת עבודה','Status-based editing capabilities'=>'יכולות עריכה מבוססות סטטוס','Relevanssi'=>'Relevanssi','Filter search results based on View Permissions for secure content discovery.'=>'סנן תוצאות חיפוש על סמך הרשאות צפייה לגילוי תוכן מאובטח.','Search result filtering'=>'סינון תוצאות חיפוש','Permission-aware indexing'=>'אינדוקס מודע הרשאות','Secure content discovery'=>'גילוי תוכן מאובטח','SearchWP'=>'SearchWP','Compatibility with SearchWP term filtering for advanced search capabilities.'=>'תאימות עם סינון מונחים של SearchWP עבור יכולות חיפוש מתקדמות.','Permission-aware search results'=>'תוצאות חיפוש מודעות הרשאות','Term-based filtering'=>'סינון מבוסס מונחים','Advanced search controls'=>'בקרות חיפוש מתקדמות','WooCommerce'=>'WooCommerce','Apply permission controls to WooCommerce products and product categories.'=>'החל הרשאות על מוצרים וקטגוריות מוצרים של WooCommerce.','Product permissions'=>'הרשאות מוצרים','Product category controls'=>'בקרות קטגוריית מוצר','WPML'=>'WPML','Multilingual support with permission synchronization across content translations.'=>'תמיכה רב-לשונית עם סנכרון הרשאות בין תרגומי תוכן.','Permission synchronization across translations'=>'סנכרון הרשאות בין תרגומים','Language-specific content access'=>'גישה לתוכן ספציפי לשפה','Multilingual permission management'=>'ניהול הרשאות רב-לשוני','Yoast SEO'=>'Yoast SEO','Exclude restricted posts from XML sitemaps to maintain proper SEO indexing.'=>'לשלול פוסטים מוגבלים מתוך מפות אתר XML כדי לשמור על אינדוקס SEO תקין.','Sitemap filtering for restricted content'=>'סינון מפות אתר עבור תוכן מוגבל','Search engine visibility controls'=>'בקרות נראות במנועי חיפוש','Permission-aware XML sitemaps'=>'מפות אתר XML מודעות להרשאות','YooTheme'=>'YooTheme','Compatibility with YooTheme builder and term permissions.'=>'התאמה עם בונה YooTheme והרשאות מונח.','Builder interface compatibility'=>'התאמה בממשק הבונה','Term permission integration'=>'אינטגרציה של הרשאות מונח','Template access controls'=>'בקרות גישה לתבניות','Viewing'=>'צפייה','Access Circles'=>'מעגלי גישה','Editing Permissions'=>'עריכת הרשאות','Compatibility Pack'=>'חבילת תאימות','Teaser'=>'תצוגה מקדימה','File Access'=>'גישה לקובץ','Membership'=>'חברות','User Posts'=>'פוסטים של משתמש','Visibility Circles and Editorial Circles block access to content not authored by other group members.'=>'מעגלי נראות ומעגלי עריכה חוסמים גישה לתוכן שלא נכתב על ידי חברי קבוצה אחרים.','Post-specific and category-specific permissions for creation and editing.'=>'הרשאות ספציפיות לפוסט ולקטגוריה ליצירה ועריכה.','Integration with ACF, bbPress, BuddyPress, Relevanssi, WPML and other plugins; enhanced Multisite support.'=>'אינטגרציה עם ACF, bbPress, BuddyPress, Relevanssi, WPML ותוספים אחרים; תמיכה משופרת במולטיסייט.','On the site front end, display teaser text for unreadable posts instead of hiding them.'=>'בצד הקדמי של האתר, הצג טקסט טיזר לפוסטים שאינם ניתנים לקריאה במקום להסתיר אותם.','Restrict direct file requests based on user\'s access to the page a file is attached to.'=>'מגביל בקשות קובץ ישירות על סמך הגישה של המשתמש לדף שאליו קובץ מחובר.','Time-limit access customizations by delaying or expiring Permission Group membership.'=>'התאמות אישיות לגישה על סמך זמן על ידי דחיית או פקיעת חברות קבוצת הרשאות.','Auto-create a page for each user of specified roles. Compatible with several Team / Staff plugins.'=>'צור עמוד אוטומטית עבור כל משתמש בתפקידים המצוינים. תואם עם מספר תוספי צוות / עובדים.','Visibility Circles and Editorial Circles block access to content not authored by other group members. Any WP Role, BuddyPress Group or custom Group can be marked as a Circle for specified post types.'=>'מעגלי נראות ומעגלי עריכה חוסמים גישה לתוכן שלא נכתב על ידי חברי קבוצה אחרים. כל תפקיד WP, קבוצת BuddyPress או קבוצה מותאמת אישית יכולים להיות מסומנים כמעגל עבור סוגי פוסטים ספציפיים.','Supports content-specific permissions for editing, term assignment and page parent selection. In combination with other modules, supports workflow statuses, PublishPress and PublishPress Revisions.'=>'תומך בהרשאות ספציפיות לתוכן עבור עריכה, הקצאת מונחים ובחירת הורה לדף. בשילוב עם מודולים אחרים, תומך במצבי עבודה, PublishPress ו-PublishPress Revisions.','Adds compatibility or integration with ACF, bbPress, Relevanssi, CMS Tree Page View, Custom Post Type UI, Subscribe2, WPML, various other plugins. Configure any BuddyPress Group as a Permissions Group. For multisite, provides network-wide Permission Groups.'=>'מוסיף תאימות או אינטגרציה עם ACF, bbPress, Relevanssi, CMS Tree Page View, Custom Post Type UI, Subscribe2, WPML ותוספים אחרים שונים. קבע כל קבוצת BuddyPress כקבוצת הרשאות. עבור מולטיסייט, מספק קבוצות הרשאות ברשת כולה.','On the site front end, replace non-readable content with placeholder text. Can be enabled for any post type. Custom filters are provided but no programming is required for basic usage.'=>'בצד הקדמי של האתר, החלף תוכן שאינו ניתן לקריאה בטקסט מחליף. ניתן לאפשר עבור כל סוג פוסט. מסננים מותאמים אישית מסופקים אך אין צורך בתכנות לשימוש בסיסי.','Filters direct file access, based on user\'s access to post(s) which the file is attached to. No additional configuration required. Creates/modifies .htaccess file in uploads folder (and in main folder for multisite).'=>'מסנן גישה ישירה לקובץ, בהתבסס על הגישה של המשתמש לפוסט(ים) שאליו קובץ מחובר. אין צורך בהגדרות נוספות. יוצר/משנה קובץ .htaccess בתיקיית העלאות (ובתיקייה הראשית עבור מולטיסייט).','Allows Permission Group membership to be date-limited (delayed and/or scheduled for expiration). Simple date picker UI alongside group membership selection.'=>'מאפשר הגבלת חברות קבוצת הרשאות לפי תאריך (נדחה ו/או מתוזמן לפקיעה). ממשק בחירת תאריך פשוט בצמוד לבחירת חברות בקבוצה.','Create or synchronize posts to match users. Designed for Team / Staff plugins, but with broad usage potential.'=>'צור או סנכרן פוסטים להתאים למשתמשים. מיועד לתוספי צוות / עובדים, אך עם פוטנציאל שימוש רחב.','If you like %s, please leave us a %s rating. Thank you!'=>'אם אתה אוהב %s, אנא השאר לנו דירוג %s. תודה!','About PublishPress Permissions'=>'על PublishPress Permissions','About'=>'אודות','Permissions Documentation'=>'תיעוד הרשאות','Documentation'=>'תיעוד','Contact the PublishPress team'=>'צור קשר עם צוות PublishPress','Contact'=>'צור קשר','Permission Group'=>'קבוצת הרשאות','Specific Permissions: restrictions (\'Blocked\') take priority over additions (\'Enabled\')'=>'הרשאות ספציפיות: הגבלות (\'חסום\') מקבלות עדיפות על פני תוספות (\'מאפשר\').','Specific Permissions: no restrictions (\'Blocked\') can be applied to custom-defined groups'=>'הרשאות ספציפיות: אין הגבלות (\'חסום\') שניתן להחיל על קבוצות שהוגדרו בהתאמה אישית','Extra Roles assignment available for {All} and {Anonymous} metagroups'=>'הקצאת תפקידים נוספים זמינה עבור {All} ו-{Anonymous} מטה-קבוצות','Allow the {All} and {Anonymous} metagroups to be granted specific reading permissions for private content'=>'אפשר לקבוצות המטריות {All} ו-{Anonymous} להינתן הרשאות קריאה ספציפיות עבור תוכן פרטי','Users who have specific editing permissions for a post or attachment can also delete it'=>'משתמשים שיש להם הרשאות עריכה ספציפיות עבור פוסט או קובץ מצורף יכולים גם למחוק אותו','Users who have custom editing permissions for an attachment can also delete it'=>'משתמשים שיש להם הרשאות עריכה מותאמות אישית עבור קובץ מצורף יכולים גם למחוק אותו','Disable front end filtering if logged user is a content administrator (normally filter to force inclusion of readable private posts in get_pages() listing, post counts, etc.'=>'כבוי סינון בחזית אם המשתמש המחובר הוא מנהל תוכן (בדרך כלל לסנן כדי לכפות הכללה של פוסטים פרטיים ניתנים לקריאה ברשימת get_pages(), ספירת פוסטים וכו\')','Disable front end filtering for all users (subject to limitation by PP_UNFILTERED_FRONT_TYPES)'=>'כבוי סינון בחזית עבור כל המשתמשים (כפוף להגבלה לפי PP_UNFILTERED_FRONT_TYPES)','Comma-separated list of post types to limit the effect of PP_UNFILTERED_FRONT and apply_filters( \'presspermit_skip_cap_filtering\' )'=>'רשימה מופרדת בפסיקים של סוגי פוסטים כדי להגביל את השפעת PP_UNFILTERED_FRONT ולהחיל_filters( \'presspermit_skip_cap_filtering\' )','Specific Permissions: additions (\'Enabled\') are not applied, cannot be assigned'=>'הרשאות ספציפיות: תוספות (\'מופעל\') לא מיועדות, לא ניתן להקצות','Don\'t assign or apply specific permissions for the \'post\' type'=>'אל תקצה או יישם הרשאות ספציפיות עבור סוג \'פוסט\'','Don\'t assign or apply specific permissions for the \'page\' type'=>'אל תקצה או יישם הרשאות ספציפיות עבור סוג \'דף\'','Don\'t assign or apply specific permissions for the \'media\' type'=>'אל תקצה או יישם הרשאות ספציפיות עבור סוג \'מדיה\'','Don\'t assign or apply specific permissions for the specified custom post type'=>'אל תקצה או החיל הרשאות ספציפיות עבור סוג הפוסט המותאם שנמסר','Include scheduled posts in the posts query if user can edit them'=>'כלול פוסטים מתוזמנים בשאילתת הפוסטים אם למשתמש יש אפשרות לערוך אותם','Don\'t filter term post counts in get_terms() call'=>'אל תסנן את ספירות הפוסטים של המונח בקריאה ל-get_terms()','Leave unreadable posts on WP Navigation Menus'=>'השאר פוסטים בלתי קריאים בתפריטי הניווט של WP','Don\'t apply CSS to hide empty Nav Menus'=>'אל תיישם CSS כדי להסתיר תפריטי ניווט ריקים','For legacy Nav Menus, hide empty nav menu div'=>'לתפריטי ניווט ישנים, הסתר את div תפריט הניווט הריק','Leave terms with no readable posts on WP Navigation Menus'=>'השאר מונחים ללא פוסטים קריאים בתפריטי הניווט של WP','When Teaser is applied with Redirect enabled, append original url as redirect_to argument'=>'כאשר טיזר מוחל עם הפניית משויכת, הוסף את ה-URL המקורי כארגומנט redirect_to','For Teaser compatibility, specify a redirect argument to use instead of redirect_to'=>'למטרת תאימות עם טיזר, ציין ארגומנט הפנייה לשימוש במקום redirect_to','For Teaser compatibility, specify an additional redirect argument other than redirect_to'=>'למטרת תאימות עם טיזר, ציין ארגומנט הפנייה נוסף מלבד redirect_to','For Teaser compatibility, prevent the pp_permissions argument from being appended to redirects'=>'למטרת תאימות עם טיזר, מנע מהארגומנט pp_permissions להיות מצורף להפניות','Filter priority for \'get_pages\' filter (default: 1)'=>'עדיפות סינון עבור סינון \'get_pages\' (ברירת מחדל: 1)','Don\'t include readable private pages in the Pages widget or other wp_list_pages() / get_pages() results    '=>'אל תכלול דפי פרטיים ניתנים לקריאה בווידג\'ט של דפים או בתוצאות אחרות של wp_list_pages() / get_pages()    ','If some pages have been suppressed from get_pages() results, change child pages\' corresponding post_parent values to a visible ancestor'=>'אם כמה דפים הוסתרו מתוצאות get_pages(), שנה את הערכים post_parent המתאימים של דפי הילדים לאבות נראים','Never modify the post_parent value in the get_pages() result set, even if some pages have been suppressed'=>'אל תשנה את ערך post_parent במערך התוצאות של get_pages(), גם אם כמה דפים הוסתרו','For performance, change the get_pages() database query to return only a subset of fields, excluding post_content'=>'למטרת ביצועים, שנה את שאילתת מסד הנתונים של get_pages() כך שתשיב רק תת-קבוצה של שדות, לא כולל post_content','Don\'t apply content teaser to get_pages() results (leave unreadable posts hidden)'=>'אל תחל על תוכן טיזר לתוצאות get_pages() (השאר פוסטים שאינם ניתנים לקריאה מוסתרים)','If some terms have been suppressed from get_terms() results, change child terms\' corresponding parent values to a visible ancestor'=>'אם כמה מונחים הוסתרו מתוצאות get_terms(), שנה את הערכים המתאימים של ההורים של המונחים לילדים לאבות נראים','Never modify the parent value in the get_terms() result set, even if some terms have been suppressed'=>'אל תשנה את ערך ההורה במערך התוצאות של get_terms(), גם אם כמה מונחים הוסתרו','Set Author to current user if autoset_post_author / autoset_page_author capability is assigned'=>'קבע את המחבר למשתמש הנוכחי אם ישנה יכולת autoset_post_author / autoset_page_author','Leave Media Library with normal access criteria based on user\'s role capabilities '=>'השאר את ספריית המדיה עם קריטריוני גישה רגילים בהתבסס על יכולות תפקיד המשתמש','Accommodate front end uploading solutions that require page editing capabilities for the async upload request'=>'התאם פתרונות העלאת קבצים בחזית שדורשים יכולות עריכת עמודים עבור בקשת ההעלאה האסינכרונית','Treat media attached to unregistered post types as unattached, to avoid improper and confusing filtering'=>'טפל במדיה שצורפה לסוגי פוסטים לא רשומים כבלתי מצורפים, כדי להימנע מסינון לא נכון ומבלבל','Attached Files Private setting available'=>'הגדרת פרטיות לקבצים מצורפים זמינה','Comma-separated list of mime types to exclude from File Access filtering'=>'רשימה מופרדת בפסיקים של סוגי mime שיש excluir מסינון גישת קבצים','Comma-separated list of mime types to include in File Access filtering (bypassing others)'=>'רשימה מופרדת בפסיקים של סוגי mime שיכללו בסינון גישת קבצים (מעקף אחרים)','When file access is blocked, do not set the WP_Query 404 / 403 property'=>'כאשר גישת הקבצים חסומה, אל תקבע את מאפיין WP_Query 404 / 403','HTTP status code to send when file access is blocked'=>'קוד מצב HTTP לשליחה כאשר גישת הקבצים חסומה','On Users listing, Permission groups in custom column are list filter links instead of group edit links'=>'ברשימת המשתמשים, קבוצות ההרשאות בעמודה מותאמת אישית הן קישורי סינון ולא קישורי עריכה קבוצתיים','Unlock Permissions > Settings > Core > Admin Back End > \'Hide non-editable posts\''=>'שחרר הרשאות > הגדרות > ליבה > ממשק ניהול אחורי > \'הסתר פוסטים שאינם ניתנים לעריכה\'','Within the async-upload.php script, filter author\'s retrieval of the attachment they just uploaded'=>'בתוך הסקריפט async-upload.php, סנן את השגת המחבר של הקובץ המצורף שהם העלו זה עתה','Don\'t filter comment display or moderation within wp-admin'=>'אל תסנן את תצוגת התגובות או המודרציה בתוך wp-admin','Allow Administrators to be added to Permission Groups, even though they are not restricted'=>'אפשר להוסיף מנהלים לקבוצות הרשאות, למרות שהם אינם מוגבלים','If propagating permissions are assigned to a page branch, overwrite any explicitly assigned permissions in sub-pages'=>'אם הרשאות המועברות משויכות לענף עמוד, כתוב מחדש כל הרשאה שהוקצתה במפורש בעמודים המשניים','Max number of specific permissions to insert in a single database query (default 1000)'=>'מספר מקסימלי של הרשאות ספציפיות להכניס בשאילתת מסד נתונים אחת (ברירת מחדל 1000)','Don\'t tweak the admin menu indexes to position Permissions menu under Users'=>'אל תשנה את האינדקסים של תפריט המנהל כדי למקם את תפריט ההרשאות מתחת למשתמשים','Don\'t add a Permissions menu. Instead, add menu items to the Users and Settings menus.'=>'אל תוסיף תפריט הרשאות. במקום זאת, הוסף פריטי תפריט לתפריטי משתמשים והגדרות.','Customize Permissions screen title for Groups'=>'התאם אישית את כותרת מסך ההרשאות עבור קבוצות','Customize Permission Groups caption on user profile'=>'התאם אישית את כותרת קבוצות ההרשאה בפרופיל המשתמש','Only one group is selectable on Add User screen'=>'רק קבוצה אחת ניתנת לבחירה במסך הוספת משתמש','Only one group is selectable on Edit User screen'=>'רק קבוצה אחת ניתנת לבחירה במסך עריכת משתמש','Display a custom hint on Permissions > User Groups'=>'הצג רמז מותאם אישית על הרשאות > קבוצות משתמשים','Max number of non-hierarchical posts / terms to display at one time (per page)'=>'מספר מקסימלי של פוסטים / מונחים לא היררכיים להציג בבת אחת (לפי עמוד)','Max number of hierarchical posts / terms to display at one time (per page)'=>'מספר מקסימלי של פוסטים / מונחים היררכיים להציג בבת אחת (לכל דף)','Disable auto-determination of how many levels of page tree to make visble by default. Instead, use specified value.'=>'בטל את קביעת האוטומטית של כמה רמות של עץ עמודים לעשות נראות כברירת מחדל. במקום זאת, השתמש בערך המוגדר.','Target number of visible pages/terms, used for auto-determination of number of visible levels'=>'מספר היעד של עמודים/מונחים נראים, שמשמש לקביעת האוטומטית של מספר הרמות הנראות','Make search function on the post selection metabox look at post content'=>'הפוך את פונקציית החיפוש על תיבת הבחירה של הפוסט לבדוק את תוכן הפוסט','Make search function on the post selection metabox look at post excerpt'=>'הפוך את פונקציית החיפוש על תיבת הבחירה של הפוסט לבדוק את תקציר הפוסט','Search by last name instead of display name'=>'חפש לפי שם משפחה במקום לפי שם תצוגה','User field to search by default'=>'שדה משתמש לחיפוש כברירת מחדל','User meta fields selectable for search (comma-separated)'=>'שדות מטא משתמשים שניתן לבחור לחיפוש (מופרדים בפסיקים)','User meta fields which should be treated as numeric (comma-separated)'=>'שדות מטא משתמשים שיש להתייחס אליהם כמספריים (מופרדים בפסיקים)','User meta fields which should be treated as boolean (comma-separated)'=>'שדות מטא משתמשים שיש להתייחס אליהם כבוליאניים (מופרדים בפסיקים)','Use display name for search results instead of user_login'=>'השתמש בשם התצוגה עבור תוצאות החיפוש במקום user_login','When synchronizing role metagroups to currently defined WP roles, don\'t delete groups for previously defined WP roles.'=>'כאשר מסנכרנים קבוצות מטא תפקידים לתפקידים המוגדרים כיום ב-WP, אל תמחק קבוצות עבור תפקידי WP שניתן להגדיר בעבר.','Force detection of WP user roles which are appended dynamically but not stored to the WP database.'=>'כפה זיהוי של תפקידי משתמש WP המתווספים דינמית אבל לא נשמרים במסד הנתונים של WP.','To save memory on front end access, don\'t register any filters related to content editing'=>'כדי לחסוך בזיכרון בגישה בחזית, אל תרשום שום מסננים הקשורים לעריכת תוכן','Attached media do not have any comments, so don\'t append clauses to comment queries for them'=>'מדיה מצורפת אין להן שום תגובות, לכן אל תוסיף סעיפים לשאילתות תגובות עבורן','Reduce overhead of pages query (in get_pages() and wp-admin) by defaulting fields to a set list that does not include post_content '=>'הפחת את העומס של שאילתות עמודים (ב-get_pages() וב-wp-admin) על ידי ברירת שדות לרשימה קבועה שאינה כוללת post_content ','Reduce overhead of wp-admin posts query by defaulting fields to a set list that does not include post_content '=>'צמצם את העומס של שאילתות הפוסטים ב-wp-admin על ידי הגדרת שדות לרשימה קבועה שאינה כוללת post_content ','Reduce overhead of wp-admin Media query by defaulting fields to a set list that does not include post_content '=>'צמצם את העומס של שאילתות המדיה ב-wp-admin על ידי הגדרת שדות לרשימה קבועה שאינה כוללת post_content ','Reduce overhead of wp-admin query for specified custom post type by defaulting fields to a set list that does not include post_content '=>'צמצם את העומס של שאילתות wp-admin עבור סוג הפוסט המותאם שצוין על ידי הגדרת שדות לרשימה קבועה שאינה כוללת post_content ','Work around database setup warnings (at plugin activation) on some servers'=>'עקוף אזהרות בהגדרת מסד הנתונים (בהפעלה של התוסף) על כמה שרתים','Development use only (suppresses post_status = \'publish\' clause for unfiltered post types with anonymous user)'=>'שימוש לפיתוח בלבד (מדכא את תנאי post_status = \'publish\' עבור סוגי פוסטים לא מסוננים עם משתמש אנונימי)','Development use only (on front end, do not replace \'post_status = \'publish\'\' clause with filtered equivalent)'=>'שימוש לפיתוח בלבד (בצד הקדמי, אל תחליף את התנאי \'post_status = \'publish\'\' עם מקבילה מסוננת)','Logged In'=>'מחובר','Not Logged In'=>'לא מחובר','Everyone'=>'כולם','Change Request Notifications'=>'התראות על בקשות שינויים','Submitted Revision Editors'=>'גרסה שהוגשה','Scheduled Change Notifications'=>'התראות על שינויים מתוזמנים','Scheduled Revision Monitors'=>'מניחי שינויים מתוזמנים','Authenticated site users, except for Administrators'=>'משתמשי אתר מאומתים, למעט מנהלים','Anonymous users (not logged in)'=>'משתמשים אנונימיים (לא מחוברים)','All users (including anonymous)'=>'כל המשתמשים (כולל אנונימיים)','All users with the WordPress role of %s'=>'כל המשתמשים עם תפקיד WordPress של %s','%1$s %2$s'=>'%1$s %2$s','%1$s won&#39;t work until you upgrade PHP to version %2$s or later. Current version: %3$s'=>'%1$s לא יעבוד עד שתחליף את PHP לגרסה %2$s או מאוחרת יותר. גרסה נוכחית: %3$s','%1$s won&#39;t work until you upgrade %2$s to version %3$s or later.'=>'%1$s לא יעבוד עד שתשדרג את %2$s לגרסה %3$s או מאוחר יותר.','%1$s won&#39;t work until you upgrade WordPress to version %2$s or later.'=>'%1$s לא יעבוד עד שתשדרג את WordPress לגרסה %2$s או מאוחר יותר.','This version of %1$s cannot work with your current %2$s version. Please upgrade it to %3$s or later.'=>'גרסה זו של %1$s אינה יכולה לעבוד עם גרסת %2$s הנוכחית שלך. אנא עדכן לגרסה %3$s או מאוחרת יותר.','Duplicate %1$s module activated (%2$s in folder %3$s).'=>'מודול כפול %1$s הופעל (%2$s בתיקייה %3$s).','Dismiss'=>'סגור','Custom Group'=>'קבוצה מותאמת אישית','Custom Groups'=>'קבוצות מותאמות אישית','Groups'=>'קבוצות','(using default capabilities due to invalid %s definition)'=>'(משתמש ביכולות ברירת מחדל עקב הגדרה לא תקינה של %s)','%1$s&nbsp;%2$s&nbsp;%3$s-&nbsp;%4$s%5$s%6$s'=>'%1$s&nbsp;%2$s&nbsp;%3$s-&nbsp;%4$s%5$s%6$s','%1$s&nbsp;%2$s%3$s'=>'%1$s&nbsp;%2$s%3$s','Your license key has expired. For updates to PublishPress Permissions Pro and priority support, %splease renew%s.'=>'מפתח הרישוי שלך פג תוקף. עבור עדכונים ל-PublishPress Permissions Pro ולתמיכה עדיפות, %sאנא חRenew%s.','[WP %s]'=>'[WP %s]','All users with a WordPress %s role'=>'כל המשתמשים עם תפקיד WordPress %s','All users who are logged in and have a role on the site'=>'כל המשתמשים שמחוברים ויש להם תפקיד באתר','Users to notify when revisions are submitted'=>'משתמשים להודיע כאשר הגרסאות מוגשות','Users to notify when scheduled revisions are published'=>'משתמשים להודיע כאשר הגרסאות המתוכננות פורסמו','(login timed out)'=>'(התחברות פגה)','View'=>'צפה','Control assignment of selected terms to %s.'=>'הקצה של מונחים נבחרים ל-%s.','Control if this %s can be selected as a Parent Page.'=>'שלוט אם %s זה יכול להיבחר כדף הורה.','Control editing of selected %s.'=>'שלוט בעריכת %s הנבחרים.','Control publishing of selected %s.'=>'שלוט בפרסום של %s הנבחרים.','Control deletion of selected %s.'=>'שלוט במחיקת %s הנבחרים.','Control term management for selected %s.'=>'שלוט בניהול מונחים עבור %s הנבחרים.','Control frontend viewing of selected %s.'=>'שלוט בהצגת קצה קדמי של %s הנבחרים.','Control who can create a revision of this %s.'=>'שלוט מי יכול ליצור גרסה של %s זו.','Control who can submit a revision of this %s.'=>'שלוט מי יכול להגיש גרסה של %s זו.','Control which terms can be set as a Parent of other terms.'=>'שלוט אילו מונחים יכולים להיות מוגדרים כהורה של מונחים אחרים.','Allow users to manage selected terms.'=>'אפשר למשתמשים לנהל מונחים שנבחרו.','Control management of selected groups.'=>'שלוט בניהול של קבוצות שנבחרו.','Enable'=>'אפשר','Block'=>'חסום','Limit to'=>'מגבלה ל','Expand access to allow specified items regardless of role capabilities or restrictions.'=>'הרחב את הגישה כדי לאפשר פריטים ספציפיים ללא קשר ליכולות או הגבלות תפקיד.','Restrict access by blocking specified items unless an "Enabled" exception is also stored.'=>'הגבל את הגישה על ידי חסימת פריטים ספציפיים אלא אם כן חריג "מאושר" נשמר גם כן.','Restrict access by limiting role capabilities to apply only for specified items. Users still need capabilities in their main role or extra roles.'=>'הגבל את הגישה על ידי הגבלת יכולות תפקידים כך שיתייחסו רק לפריטים ספציפיים. משתמשים עדיין צריכים יכולות בתפקיד הראשי או בתפקידים נוספים.','Using group membership to block access is not recommended. Consider reducing the user\'s role capabilities and using group membership to add access.'=>'שימוש בחברות קבוצתית כדי לחסום גישה אינו מומלץ. שקול להפחית את יכולות התפקיד של המשתמש ולהשתמש בחברות קבוצתית כדי להוסיף גישה.','Selected:'=>'נבחר:','Nav Menus (Legacy)'=>'תפריטי ניווט (מורשת)','Legacy'=>'מורשת','%s:'=>'%s:','Selected %s:'=>'נבחר %s:','Sub-%s:'=>'תת-%s:','All Statuses'=>'כל הסטטוסים','%s Visibility'=>'%s נראות','No user/group specified.'=>'לא צוין משתמש/קבוצה.','You are not permitted to do that.'=>'אינך מורשה לעשות זאת.','Invalid user ID.'=>'מזהה משתמש לא חוקי.','Invalid group ID.'=>'מזהה קבוצה לא חוקי.','Roles updated.'=>'תפקידים עודכנו.','Specific Permissions updated.'=>'הרשאות ספציפיות עודכנו.','Roles and Permissions copied.'=>'תפקידים והרשאות הועתקו.','Group updated.'=>'הקבוצה עודכנה.','Back to permissions list'=>'חזרה לרשימת הרשאות','Edit User Permissions'=>'ערוך הרשאות משתמש','Add User Permissions'=>'הוסף הרשאות משתמש','Edit Permissions'=>'ערוך הרשאות','Edit Permissions (%s)'=>'ערוך הרשאות (%s)','%sEdit WordPress Role%s'=>'%sערוך תפקיד WordPress%s','Edit role capabilities directly'=>'ערוך יכולות תפקיד ישירות','Add New'=>'הוסף חדש','Name:'=>'שם:','Email:'=>'דוא"ל:','Primary Role:'=>'תפקיד ראשי:','User ID:'=>'מזהה משתמש:','Member since:'=>'חבר מאז:','Description:'=>'תיאור:','Update Permissions'=>'עדכן הרשאות','View Full Profile'=>'צפה בפר